    if inventory.get("snapshot_mode") != CURRENT_SNAPSHOT_MODE:
        return

    for name in ("pilot_report.json", "batch_report.jsonl", "final_validation_summary.json", "COMPLETE.md"):
        if not (run_dir / name).exists():
